// Generate remaining roadmaps programmatically for branches that don't have custom ones
// This ensures all branches have roadmap data even if not explicitly defined above
(function generateRemainingRoadmaps(){
  BRANCHES.forEach(function(b){
    if(ROADMAPS[b.id]) return; // Already has a custom roadmap
    // Generate a sensible default roadmap based on branch data
    ROADMAPS[b.id]={
      whyFits:b.name+' aligns with your profile because '+b.desc.charAt(0).toLowerCase()+b.desc.slice(1)+' '+b.whoSuits.replace('Students who','You'),
      yearByYear:[
        {year:'Year 1',items:['Engineering Mathematics','Physics & Chemistry','Basic Sciences','Introduction to '+b.name.split(' ')[0]+' Concepts','Engineering Graphics','Communication Skills']},
        {year:'Year 2',items:[b.coreSkills[0]||'Core Subject 1',b.coreSkills[1]||'Core Subject 2','Applied Mathematics','Laboratory Practice','Workshop/Field Training','Technical Communication']},
        {year:'Year 3',items:[b.coreSkills[2]||'Advanced Subject 1',b.coreSkills[3]||'Advanced Subject 2',b.coreSkills[4]||'Specialization Elective','Industry Exposure','Project Work','Seminar']},
        {year:'Year 4',items:[b.coreSkills[5]||'Advanced Elective','Industry Internship','Capstone Project','Research Paper/Seminar','Professional Ethics','Technical Elective']}
      ],
      coreSubjects:b.coreSkills.slice(0,8),
      tools:b.tools.concat(['Excel']).slice(0,9),
      projects:[
        'Design and implement a '+b.coreSkills[0]+' project',
        'Build a practical application using '+b.tools[0],
        'Develop a '+b.name.toLowerCase()+' solution for industry',
        'Create a simulation/analysis project using '+b.tools[1],
        'Research and present on emerging trends in '+b.name
      ],
      internshipStrategy:'Target companies in the '+CLUSTERS[b.cluster].name+' sector. Build a strong project portfolio demonstrating '+b.coreSkills[0]+' and '+b.coreSkills[1]+' skills. Seek industry mentorship during Year 3.',
      skillMilestones:[
        'Sem 1-2: Build strong fundamentals in core sciences and mathematics',
        'Sem 3-4: Develop proficiency in '+b.coreSkills[0]+' and '+b.coreSkills[1],
        'Sem 5: First industry internship or research project',
        'Sem 6: Advanced specialization in '+b.coreSkills[2],
        'Sem 7-8: Industry-ready portfolio and placement preparation'
      ],
      careerPaths:b.careers.slice(0,6),
      topRecruiters:['Industry leaders in '+CLUSTERS[b.cluster].name+' sector','Research institutions','Government organizations','Private companies','Startups','Consulting firms','Manufacturing firms','MNCs'],
      salaryDirection:'Starting: ₹3-10 LPA | Mid-career: ₹10-25 LPA | Senior: ₹25-45+ LPA. Specialization and industry experience significantly impact compensation.',
      higherEd:['M.Tech in '+b.name,'MS in related field (abroad)','MBA for management track','Research PhD for academic careers'],
      futureTrends:['Industry 4.0 integration','AI and automation in '+b.name.split(' ')[0].toLowerCase()+' sector','Sustainability and green practices','Digital transformation','Emerging technologies adoption'],
      risks:['Industry-specific market fluctuations','Requires continuous skill upgrades','Competition from adjacent fields','May need higher education for research roles'],
      actionPlan:[
        'Master core skills: '+b.coreSkills[0]+' and '+b.coreSkills[1],
        'Build 3+ significant projects demonstrating practical skills',
        'Complete an industry internship by Year 3',
        'Get relevant certifications in '+b.tools[0]+' or '+b.tools[1],
        'Develop strong technical communication and teamwork skills'
      ]
    };
  });
})();


